@page "/settings"
@using sv_e0ca1211f23e4d6a855dfb8a3eea9a0d.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (_profile is not null)
                {
                    <div class="profile-layout">
                        <div class="avatar-area">
                            <div class="avatar-preview">
                                <img src="@_editProfile.AvatarUrl" alt="Avatar" />
                            </div>
                            <span class="avatar-url">@_editProfile.AvatarUrl</span>
                        </div>
                        <div class="form-fields">
                            <div class="form-group">
                                <label for="displayName">Display Name</label>
                                <input id="displayName" type="text" @bind="_editProfile.DisplayName" />
                            </div>
                            <div class="form-group">
                                <label for="email">Email</label>
                                <input id="email" type="email" @bind="_editProfile.Email" />
                            </div>
                            <div class="form-group">
                                <label for="bio">Bio</label>
                                <textarea id="bio" rows="4" @bind="_editProfile.Bio"></textarea>
                            </div>
                            <div class="button-group">
                                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                            </div>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (_notificationPrefs is not null)
                {
                    <div class="form-fields">
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Email Notifications</span>
                                <input type="checkbox" @bind="_editNotifications.EmailNotifications" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Push Notifications</span>
                                <input type="checkbox" @bind="_editNotifications.PushNotifications" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>
                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Weekly Digest</span>
                                <input type="checkbox" @bind="_editNotifications.WeeklyDigest" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>

                        <h3>Muted Channels</h3>
                        <div class="channel-list">
                            @foreach (var channel in _allChannels)
                            {
                                <label class="channel-item">
                                    <input type="checkbox"
                                           checked="@_editNotifications.MutedChannels.Contains(channel)"
                                           @onchange="e => ToggleMutedChannel(channel, (bool)(e.Value ?? false))" />
                                    <span>@channel</span>
                                </label>
                            }
                        </div>

                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (_securitySettings is not null)
                {
                    <div class="form-fields">
                        <div class="expandable-panel">
                            <button class="panel-header" @onclick="TogglePasswordPanel">
                                <span>Change Password</span>
                                <span class="expand-icon">@(_passwordPanelExpanded ? "▼" : "▶")</span>
                            </button>
                            @if (_passwordPanelExpanded)
                            {
                                <div class="panel-body">
                                    <div class="form-group">
                                        <label for="currentPassword">Current Password</label>
                                        <input id="currentPassword" type="password" @bind="_currentPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="newPassword">New Password</label>
                                        <input id="newPassword" type="password" @bind="_newPassword" />
                                    </div>
                                    <div class="form-group">
                                        <label for="confirmPassword">Confirm Password</label>
                                        <input id="confirmPassword" type="password" @bind="_confirmPassword" />
                                    </div>
                                    <button class="btn-primary" @onclick="UpdatePassword">Update Password</button>
                                </div>
                            }
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Two-Factor Authentication</span>
                                <input type="checkbox" @bind="_twoFactorEnabled" />
                                <span class="toggle-switch"></span>
                            </label>
                            <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                                @(_twoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </div>

                        @if (_securitySettings.LastPasswordChange.HasValue)
                        {
                            <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                        }

                        <h3>Active Sessions</h3>
                        <div class="sessions-table-wrapper">
                            <table class="sessions-table">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in _securitySettings.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@FormatLastActive(session.LastActive)</td>
                                            <td>
                                                @if (session.Id != _currentSessionId)
                                                {
                                                    <button class="btn-danger-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                                }
                                                else
                                                {
                                                    <span class="current-badge">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>
                    </div>
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (_appearance is not null)
                {
                    <div class="form-fields">
                        <div class="form-group">
                            <label>Theme</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Light"
                                           checked="@(_editAppearance.Theme == "Light")"
                                           @onchange='() => _editAppearance.Theme = "Light"' />
                                    <span>Light</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="Dark"
                                           checked="@(_editAppearance.Theme == "Dark")"
                                           @onchange='() => _editAppearance.Theme = "Dark"' />
                                    <span>Dark</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="theme" value="System"
                                           checked="@(_editAppearance.Theme == "System")"
                                           @onchange='() => _editAppearance.Theme = "System"' />
                                    <span>System</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label>Font Size</label>
                            <div class="radio-group">
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Small"
                                           checked="@(_editAppearance.FontSize == "Small")"
                                           @onchange='() => _editAppearance.FontSize = "Small"' />
                                    <span>Small</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Medium"
                                           checked="@(_editAppearance.FontSize == "Medium")"
                                           @onchange='() => _editAppearance.FontSize = "Medium"' />
                                    <span>Medium</span>
                                </label>
                                <label class="radio-label">
                                    <input type="radio" name="fontSize" value="Large"
                                           checked="@(_editAppearance.FontSize == "Large")"
                                           @onchange='() => _editAppearance.FontSize = "Large"' />
                                    <span>Large</span>
                                </label>
                            </div>
                        </div>

                        <div class="form-group">
                            <label for="language">Language</label>
                            <select id="language" @bind="_editAppearance.Language">
                                <option value="English">English</option>
                                <option value="Spanish">Spanish</option>
                                <option value="French">French</option>
                                <option value="German">German</option>
                                <option value="Japanese">Japanese</option>
                                <option value="Chinese">Chinese</option>
                            </select>
                        </div>

                        <div class="toggle-group">
                            <label class="toggle-label">
                                <span>Compact Mode</span>
                                <input type="checkbox" @bind="_editAppearance.CompactMode" />
                                <span class="toggle-switch"></span>
                            </label>
                        </div>

                        <h3>Live Preview</h3>
                        <div class="live-preview @GetPreviewClasses()">
                            <div class="preview-header">Preview Header</div>
                            <div class="preview-body">
                                <p>This is a preview of how your content will look with the selected appearance settings.</p>
                                <button class="preview-button">Sample Button</button>
                            </div>
                        </div>

                        <div class="button-group">
                            <button class="btn-primary" @onclick="SaveAppearance">Save</button>
                        </div>
                    </div>
                }
            </section>
        }
    </main>
</div>

@if (_showRevokeConfirmation)
{
    <div class="modal-overlay" @onclick="CancelRevoke">
        <div class="modal-dialog" @onclick:stopPropagation="true">
            <h3>Revoke Session</h3>
            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
            <p>This will immediately sign out that device.</p>
            <div class="modal-actions">
                <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
            </div>
        </div>
    </div>
}

@code {
    private string ActiveSection { get; set; } = "Profile";

    // Toast
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile
    private UserProfile? _profile;
    private EditableProfile _editProfile = new();

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private EditableNotifications _editNotifications = new();
    private readonly List<string> _allChannels = new() { "general", "marketing", "announcements", "engineering", "design", "support" };

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private string _currentSessionId = "session-1";
    private bool _showRevokeConfirmation;
    private ActiveSession? _sessionToRevoke;

    // Appearance
    private AppearanceSettings? _appearance;
    private EditableAppearance _editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
    }

    private async Task LoadAllSettings()
    {
        _profile = await SettingsService.GetProfileAsync();
        _editProfile = new EditableProfile
        {
            DisplayName = _profile.DisplayName,
            Email = _profile.Email,
            AvatarUrl = _profile.AvatarUrl,
            Bio = _profile.Bio
        };

        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications = new EditableNotifications
        {
            EmailNotifications = _notificationPrefs.EmailNotifications,
            PushNotifications = _notificationPrefs.PushNotifications,
            WeeklyDigest = _notificationPrefs.WeeklyDigest,
            MutedChannels = new List<string>(_notificationPrefs.MutedChannels)
        };

        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;

        _appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance = new EditableAppearance
        {
            Theme = _appearance.Theme,
            FontSize = _appearance.FontSize,
            Language = _appearance.Language,
            CompactMode = _appearance.CompactMode
        };
    }

    private void SetSection(string section)
    {
        ActiveSection = section;
        DismissToast();
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editProfile.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (_profile is not null)
        {
            _editProfile = new EditableProfile
            {
                DisplayName = _profile.DisplayName,
                Email = _profile.Email,
                AvatarUrl = _profile.AvatarUrl,
                Bio = _profile.Bio
            };
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notification methods
    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted && !_editNotifications.MutedChannels.Contains(channel))
        {
            _editNotifications.MutedChannels.Add(channel);
        }
        else if (!muted)
        {
            _editNotifications.MutedChannels.Remove(channel);
        }
    }

    private async Task SaveNotifications()
    {
        var updated = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            new List<string>(_editNotifications.MutedChannels)
        );
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _notificationPrefs = updated;
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private void TogglePasswordPanel() => _passwordPanelExpanded = !_passwordPanelExpanded;

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword))
        {
            ShowToast("Please enter your current password.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("Please enter a new password.", "error");
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelExpanded = false;
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirmation = true;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
        _showRevokeConfirmation = false;
    }

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast($"Session on {_sessionToRevoke.Device} has been revoked.", "success");
        }
        _showRevokeConfirmation = false;
        _sessionToRevoke = null;
    }

