+
+/* Radio Group */
+.radio-group {
+    display: flex;
+    gap: 1.25rem;
+    flex-wrap: wrap;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+    font-weight: 400;
+    color: #4a5568;
+}
+
+/* Live Preview */
+.live-preview {
+    border: 1px solid #e2e8f0;
+    border-radius: 8px;
+    overflow: hidden;
+    transition: all 0.2s ease;
+}
+
+.preview-header {
+    padding: 0.75rem 1rem;
+    font-weight: 600;
+    border-bottom: 1px solid #e2e8f0;
+}
+
+.preview-body {
+    padding: 1rem;
+}
+
+.preview-body p {
+    margin: 0 0 0.75rem;
+}
+
+.preview-button {
+    padding: 0.5rem 1rem;
+    border-radius: 6px;
+    border: none;
+    cursor: pointer;
+    font-weight: 500;
+}
+
+/* Preview Themes */
+.preview-theme-light {
+    background: #ffffff;
+    color: #1a202c;
+}
+
+.preview-theme-light .preview-header { background: #f7fafc; }
+.preview-theme-light .preview-button { background: #3182ce; color: #fff; }
+
+.preview-theme-dark {
+    background: #1a202c;
+    color: #e2e8f0;
+    border-color: #4a5568;
+}
+
+.preview-theme-dark .preview-header { background: #2d3748; border-color: #4a5568; }
+.preview-theme-dark .preview-button { background: #63b3ed; color: #1a202c; }
+
+.preview-theme-system {
+    background: #f0f4f8;
+    color: #2d3748;
+}
+
+.preview-theme-system .preview-header { background: #e2e8f0; }
+.preview-theme-system .preview-button { background: #4299e1; color: #fff; }
+
+/* Preview Font Sizes */
+.preview-font-small { font-size: 0.8rem; }
+.preview-font-medium { font-size: 1rem; }
+.preview-font-large { font-size: 1.2rem; }
+
+/* Preview Compact */
+.preview-compact .preview-header { padding: 0.4rem 0.75rem; }
+.preview-compact .preview-body { padding: 0.5rem 0.75rem; }
+.preview-compact .preview-body p { margin-bottom: 0.4rem; }
+
+/* Buttons */
+.button-group {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 0.5rem;
+}
+
+.btn-primary {
+    padding: 0.625rem 1.25rem;
+    background: #3182ce;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.15s ease;
+}
+
+.btn-primary:hover { background: #2c5282; }
+
+.btn-secondary {
+    padding: 0.625rem 1.25rem;
+    background: #fff;
+    color: #4a5568;
+    border: 1px solid #e2e8f0;
+    border-radius: 6px;
+    font-weight: 500;
+    cursor: pointer;
+    transition: all 0.15s ease;
+}
+
+.btn-secondary:hover { background: #f7fafc; border-color: #cbd5e0; }
+
+.btn-danger {
+    padding: 0.625rem 1.25rem;
+    background: #e53e3e;
+    color: #fff;
+    border: none;
+    border-radius: 6px;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.15s ease;
+}
+
+.btn-danger:hover { background: #c53030; }
+
+.btn-danger-sm {
+    padding: 0.35rem 0.75rem;
+    background: #fff;
+    color: #e53e3e;
+    border: 1px solid #e53e3e;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: all 0.15s ease;
+}
+
+.btn-danger-sm:hover { background: #e53e3e; color: #fff; }
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 2000;
+}
+
+.modal-dialog {
+    background: #fff;
