+}
+
+.modal-dialog p {
+    color: #4a5568;
+    margin: 0 0 0.5rem;
+}
+
+.modal-actions {
+    display: flex;
+    justify-content: flex-end;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+}
+
+.info-text {
+    font-size: 0.875rem;
+    color: #718096;
+    margin: 0;
+}
